<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, shallowRef, watch } from "vue";
import { createDirectoryController, parseTeachingTable, TEACHING_KINDS, teachingDraftRows, teachingColumn, teachingImportRows, type TeachingDraftRow } from "./directory_session";
import { createDirectoryApi, type DirectoryApi } from "./directory_api";
import { displayField, type DirectoryField, type DirectoryChange, type DirectoryQueryInput, type DirectoryQuery, type DirectoryRecord } from "./directory_contracts";
import { directoryFieldValue } from "./directory_labels";
import DirectoryResult from "./DirectoryResult.vue";
import DirectoryProposal from "./DirectoryProposal.vue";
import FamilyCorrectionRecords from "./FamilyCorrectionRecords.vue";
import {familyFieldLabels} from "./family_contracts";
import {correctionFieldsByKind,correctionFieldLabels} from "./family_corrections";
const props = defineProps<{ identityLabel: string; title?: string; identityInvalid?: boolean; api?: DirectoryApi; familyCorrections?:boolean; education?: boolean; batch?: boolean; residenceImports?: boolean; packageMode?: boolean }>();
const emit = defineEmits<{ identityInvalid: []; operationResult: [proposalRef: string]; packageInput:[request:DirectoryChange,label:string] }>();
const api = props.api ?? createDirectoryApi();
const authoritativeReceipts = new WeakSet<object>();
async function observeResult(kind: "confirm" | "receipt", reference: string) {
  const receipt = await api[kind](reference);
  authoritativeReceipts.add(receipt);
  return receipt;
}
const controller = createDirectoryController({ ...api, confirm: reference => observeResult("confirm", reference), receipt: reference => observeResult("receipt", reference) }, {residenceImports: props.residenceImports, ...(props.packageMode?{stage:(request:DirectoryChange)=>{emit("packageInput",request,state.value.selected?.label??state.value.descriptor?.creation_choices.find(c=>c.creation_ref===state.value.creation)?.label??props.title??"\u5f85\u6838\u5bf9\u8d44\u6599");}}:{})});
async function operationResult(kind: "confirm" | "checkReceipt") {
  if (state.value.busy || state.value.authentication_required) return;
  const applied = await controller[kind]();
  await nextTick();
  const receipt = state.value.receipt;
  if (applied && receipt && receipt.status !== "unknown" && !state.value.authentication_required && authoritativeReceipts.delete(receipt)) {
    emit("operationResult", receipt.reference);
  }
}
const state = shallowRef(controller.getState()); const unsubscribe = controller.subscribe(value => { state.value = value; if (value.authentication_required) emit("identityInvalid"); });
watch(() => props.identityInvalid, value => { if (value) controller.invalidateIdentity(); }, { immediate: true, flush: "sync" });
const relatedKind = ref("");
const dependencyYear=ref(""); const dependencyCampus=ref(""); const dependencyPosition=ref("");
const dependencyKind=computed(()=>props.education && ["fact_quality","policy_scope"].includes(state.value.family));
const queryText = ref(""); const asOf = ref(""); const relatedRef = ref(""); const relatedField = ref(""); const relatedLabel = ref(""); const creating = ref(""); const acknowledged = ref(false);
const locked = computed(() => state.value.authentication_required || state.value.busy || state.value.receipt?.status === "unknown");
const nameSupported = computed(() => !state.value.descriptor?.query_support || state.value.descriptor.query_support.name_fields.length > 0);
const relatedOptions = computed(() => state.value.descriptor?.query_support?.related_fields?.filter(item => item.kind === relatedKind.value) ?? []);
const relatedSupported = computed(() => {
  if (!relatedRef.value || !state.value.descriptor?.query_support) return true;
  if (!state.value.descriptor.query_support.related_kinds.includes(relatedKind.value)) return false;
  return !state.value.descriptor.query_support.related_fields || relatedOptions.value.some(item => item.field === relatedField.value);
});
const editing = computed(() => state.value.selected !== null || state.value.creation !== null);
const correctionField=ref('');const correctionAction=ref<'end'|'revoke'|''>('');
const correctionOptions=computed(()=>correctionFieldsByKind[state.value.family]??[]);
watch(()=>state.value.selected?.reference,()=>{correctionField.value='';correctionAction.value='';});
const residenceOperations=computed<DirectoryChange['operation'][]|null>(()=>{
 if(!props.residenceImports)return null;
 if(state.value.creation)return ['upsert'];
 if(['dormitory_building_profile','dorm_room','dorm_bed'].includes(state.value.family))return ['upsert','end','correct','cancel'];
 if(state.value.family==='student_bed_residence')return ['end','revoke','cancel'];
 if(state.value.family==='student_school_relationship')return ['upsert','end','correct','revoke'];
 return null;
});
const supportedOperation=computed(()=>!residenceOperations.value||residenceOperations.value.includes(state.value.operation));
const residenceNeedsTime=computed(()=>props.residenceImports&&['correct','cancel','end'].includes(state.value.operation));
const showFields = computed(() => ["upsert", "reactivate", "correct"].includes(state.value.operation));
const rootKinds = ["school", "person", "organization", "location"];
const teaching = computed(()=>props.education && TEACHING_KINDS.includes(state.value.family));
const importText=ref("");const importMode=ref<"incremental"|"replace">("incremental");const replacementRefs=ref<string[]>([]);const importError=ref("");
const residenceMode=ref<"incremental"|"replace">("incremental");const residenceRefs=ref<string[]>([]);const residenceIncludeCurrent=ref(true);
async function prepareResidence(){acknowledged.value=false;importError.value="";if(!await controller.prepareResidenceImport(residenceMode.value,residenceRefs.value,residenceIncludeCurrent.value))importError.value=state.value.error??"请选择获准住宿范围、明确生效时间及维护原因；清空集合须显式选择完整替换。";}
async function prepareCurrent(){if(!supportedOperation.value||(residenceNeedsTime.value&&!state.value.effectiveAt))return;if(props.residenceImports && state.value.family==="student_bed_residence" && residenceMode.value==="replace")await prepareResidence();else await controller.prepare();}
watch(()=>state.value.result,value=>{if(value)residenceRefs.value=[];});
watch([residenceMode,residenceRefs,residenceIncludeCurrent],()=>{acknowledged.value=false;controller.setReason(state.value.reason);},{deep:true,flush:"sync"});
watch(()=>state.value.family,()=>{residenceMode.value="incremental";residenceRefs.value=[];residenceIncludeCurrent.value=true;});
const tableRows=ref<TeachingDraftRow[]>([]);
const tableFields=computed(()=>state.value.descriptor?.fields.filter(f=>!["references","object","lines"].includes(f.type))??[]);
function fillTable(){if(!state.value.descriptor)return;tableRows.value=teachingDraftRows(state.value.descriptor,state.value.result?.records??[]);}
function appendCurrentToTable(){const d=state.value.descriptor;if(!d)return;const reference=state.value.selected?.reference??state.value.creation;if(!reference)return;const record={...state.value.selected,reference,fact_kind:d.fact_kind,label:state.value.selected?.label??d.creation_choices.find(c=>c.creation_ref===reference)?.label??"新增登记",fields:{...state.value.selected?.fields,...state.value.fields}} as DirectoryRecord;const draft=teachingDraftRows(d,[record])[0];tableRows.value=[...tableRows.value.filter(r=>r.values.reference!==reference),draft];}
async function prepareTable(){importError.value="";acknowledged.value=false;if(!await controller.prepareImport(teachingImportRows(tableRows.value),importMode.value,replacementRefs.value))importError.value=state.value.error??"请核对条目、维护原因与替换集合。";}
watch(()=>state.value.result,()=>{tableRows.value=[];});
watch(()=>state.value.authentication_required,invalid=>{if(invalid)tableRows.value=[];});
function roleLabels(field:DirectoryField):Record<string,string>{return field.options.length?Object.fromEntries(field.options.map(o=>[o.value,o.label])):{primary:"班主任",deputy:"副班主任",joint:"共同班主任",acting:"代任老师"};}
async function prepareImport(){if(!state.value.descriptor)return;importError.value="";acknowledged.value=false;try{const rows=parseTeachingTable(importText.value,state.value.descriptor);if(!await controller.prepareImport(rows,importMode.value,replacementRefs.value))importError.value=state.value.error??"请核对获权对象引用、维护原因和显式替换集合。";}catch(error){importError.value=error instanceof Error?error.message:"教学表格内容无效。";}}
const importColumns=computed(()=>["reference","operation",...(state.value.descriptor?.fields.map(f=>f.name.endsWith("_refs")?f.name.slice(0,-5)+"_source_keys":f.name.endsWith("_ref")?f.name.slice(0,-4)+"_source_key":f.name)??[])]);
function fillImportTemplate(){importText.value=importColumns.value.join("\t")+"\n"+(state.value.selected?.reference??state.value.creation??"")+"\tupsert";}
watch(()=>state.value.family,()=>{tableRows.value=[];importText.value="";replacementRefs.value=[];importMode.value="incremental";importError.value="";});
function roleValue(field: DirectoryField, role: string) { const value=state.value.fields[field.name] ?? state.value.selected?.fields[field.name]; return value && typeof value === "object" && !Array.isArray(value) ? value[role] ?? "" : ""; }
function changeRole(field: DirectoryField, role: string, event: Event) { const value=state.value.fields[field.name] ?? state.value.selected?.fields[field.name]; const next={...(value && typeof value === "object" && !Array.isArray(value) ? value : {})}; const raw=(event.target as HTMLInputElement).value; if(raw) next[role]=Number(raw); else delete next[role]; controller.setField(field.name,next); acknowledged.value=false; }
function moveReference(field: DirectoryField, index:number, delta:number) { const raw=state.value.fields[field.name] ?? state.value.selected?.fields[field.name]; if(!Array.isArray(raw)) return; const values=[...raw]; const other=index+delta; if(other<0 || other>=values.length) return; [values[index],values[other]]=[values[other],values[index]]; controller.setField(field.name,values); }
function selectedReferences(field:DirectoryField): string[] {const values=state.value.fields[field.name] ?? state.value.selected?.fields[field.name];return Array.isArray(values)?values:[];}
function batchReferences(field:"student_ref"|"old_class_ref"|"replace_refs",kind:string,event:Event) { controller.setBatchReference(field,kind,Array.from((event.target as HTMLSelectElement).selectedOptions).map(option=>option.value).filter(Boolean)); acknowledged.value=false; }
function changeReferences(field: DirectoryField,event:Event) { controller.setField(field.name,Array.from((event.target as HTMLSelectElement).selectedOptions).map(option=>option.value)); acknowledged.value=false; }
function inputValue(field: DirectoryField) { const value = state.value.fields[field.name] ?? state.value.selected?.fields[field.name]; if (field.type === "lines") return Array.isArray(value) ? value.join("\n") : ""; if (field.type === "datetime" && typeof value === "string") { const date = new Date(value); if (Number.isFinite(date.getTime())) return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 16); } return value ?? ""; }
function currentValue(field: DirectoryField) { const value = state.value.selected?.fields[field.name]; return displayField(field.options.find(option => option.value === value)?.label ?? directoryFieldValue(field.name, value)); }
function changeField(field: DirectoryField, event: Event) { const raw = (event.target as HTMLInputElement).value; const value = raw === "" ? null : field.type === "boolean" ? raw === "true" : field.type === "number" ? Number(raw) : field.type === "datetime" ? new Date(raw).toISOString() : field.type === "lines" ? raw.split(/\r?\n/).map(s => s.trim()).filter(Boolean) : raw; controller.setField(field.name, value); acknowledged.value = false; }
async function chooseFamily(event: Event) { queryText.value = ""; relatedField.value = ""; creating.value = ""; acknowledged.value = false; await controller.chooseFamily((event.target as HTMLSelectElement).value); }
function query(all = false) { if(all && state.value.descriptor?.query_support?.all_authorized===false) return; if (!all && (!relatedSupported.value || (!nameSupported.value && queryText.value.trim()))) return; const input: DirectoryQueryInput = { fact_kind: state.value.family, ...(dependencyKind.value ? {...(dependencyYear.value ? {academic_year:Number(dependencyYear.value)}:{}),...(dependencyCampus.value ? {campus_ref:dependencyCampus.value}:{}),...(dependencyPosition.value ? {position_ref:dependencyPosition.value}:{})}:{}), scope: all ? "all_authorized" : "selected", ...(asOf.value ? { as_of: new Date(asOf.value).toISOString() } : {}), ...(!all && queryText.value.trim() ? { query_text: queryText.value.trim() } : {}), ...(!all && relatedRef.value ? { ...(relatedField.value ? { related_field: relatedField.value } : {}), related_ref: relatedRef.value } : {}) }; acknowledged.value = false; void controller.query(input); }
function related(reference: string) { const record = state.value.result?.records.find(r => r.reference === reference); if (!record) return; relatedRef.value = reference; relatedKind.value = record.fact_kind; relatedField.value = ""; relatedLabel.value = record.label; queryText.value = ""; }
async function reviewProposal(reference: string) { acknowledged.value = false; await controller.reviewProposal(reference); }
function selectRelated(result: DirectoryQuery, reference: string) { if (locked.value) return; const record = result.records.find(row => row.reference === reference); if (!record) return; relatedRef.value = reference; relatedKind.value = record.fact_kind; relatedField.value = ""; relatedLabel.value = record.label; queryText.value = ""; }
defineExpose({ reviewProposal, selectRelated });
onMounted(async () => { await controller.open(); if (state.value.families[0]) await controller.chooseFamily(state.value.families[0].value); });
onUnmounted(() => { unsubscribe(); controller.dispose(); queryText.value = ""; relatedRef.value = ""; });
</script>
<template>
  <section class="directory-workbench" :aria-label="title ?? '基础目录与事实维护'">
    <h2>{{title ?? "基础目录与事实维护"}}</h2><p>{{ state.authentication_required ? "身份已失效，以下保留旧资料与草稿" : "当前履职身份：" + identityLabel }}</p>
    <p class="note">每项查询和维护分别按当前职责核验；能查看对象不代表能修改。这里只维护正式事实，服务目录不代表已办理服务。</p>
    <label>事实类型<select data-role="directory-family" :value="state.family" :disabled="locked" @change="chooseFamily"><option v-for="family in state.families" :key="family.value" :value="family.value">{{ family.label }}</option></select></label>
    <p v-if="state.descriptor?.query_support" aria-label="查询能力说明">{{ state.descriptor.query_support.guidance }}</p>
    <form class="form" @submit.prevent="query()"><label>精确名称或字段值（选填）<input v-model="queryText" maxlength="1000" :disabled="state.authentication_required || state.busy || !nameSupported" /></label><label>事实时点（选填，留空查询当前）<input v-model="asOf" type="datetime-local" :disabled="state.authentication_required || state.busy" /></label>
      <p v-if="relatedRef">关联对象：{{ relatedLabel }}（{{ relatedRef }}）。选择要查询的事实类型后，点击查询关联事实。<button type="button" :disabled="state.authentication_required || state.busy" @click="relatedRef = ''; relatedField = ''; relatedLabel = ''">清除关联对象</button></p>
      <label v-if="relatedRef && state.descriptor?.query_support?.related_fields">关联字段<select data-role="related-field" v-model="relatedField" :disabled="locked"><option value="">请选择明确关联字段</option><option v-for="item in relatedOptions" :key="item.field" :value="item.field">{{ item.label }}</option></select></label>
      <p v-if="!relatedSupported" role="status">当前类型不支持此关联对象，请选择支持的事实类型或清除关联对象。</p>
      <fieldset v-if="dependencyKind"><legend>依据适用条件</legend><label>明确学年起始年（可不填）<input v-model="dependencyYear" type="number" min="1" max="9999" :disabled="locked" /></label>
        <label>校区条件<button type="button" :disabled="locked" @click="controller.loadBatchChoices('location')">获取获权地点</button><select v-model="dependencyCampus" :disabled="locked"><option value="">不含限定校区的依据</option><option v-for="row in state.batchChoices.location ?? []" :key="row.reference" :value="row.reference">{{row.label}}</option></select></label>
        <label v-if="state.family==='fact_quality'">班内岗位条件<button type="button" :disabled="locked" @click="controller.loadBatchChoices('class_position_definition')">获取获权岗位</button><select v-model="dependencyPosition" :disabled="locked"><option value="">不含限定岗位的依据</option><option v-for="row in state.batchChoices.class_position_definition ?? []" :key="row.reference" :value="row.reference">{{row.label}}</option></select></label><p>未填学年时，仅查询未限定学年的依据。适用条件同时成立才返回。</p>
      </fieldset>
      <button type="submit" :disabled="state.authentication_required || state.busy || !state.family || !relatedSupported">{{ relatedRef ? "查询关联事实" : "查询正式事实" }}</button><button type="button" :disabled="state.authentication_required || state.busy || !state.family || state.descriptor?.query_support?.all_authorized===false" @click="query(true)">查看本类型获权集合</button>
    </form>
    <p v-if="state.busy" role="status">正在核对正式资料……</p><p v-if="state.error" role="alert" class="error">{{ state.error }}</p>
    <DirectoryResult @identity-invalid="controller.invalidateIdentity" v-if="state.result" :key="state.result.queried_at + state.result.fact_kind" :result="state.result" editable :disabled="locked" @edit="controller.edit" @related="related" />
    <button v-if="state.result?.next_cursor" type="button" data-action="directory-next-page" :disabled="locked" @click="controller.loadMore">查看下一批获准结果</button>
    <div v-if="state.descriptor?.creation_choices.length" class="form"><label>已获准创建项<select v-model="creating" :disabled="locked"><option value="">请选择明确创建项</option><option v-for="choice in state.descriptor.creation_choices" :key="choice.creation_ref" :value="choice.creation_ref">{{ choice.label }}</option></select></label><button type="button" :disabled="locked || !creating" @click="controller.create(creating)">填写新对象</button></div>
    <form v-if="editing" class="form maintenance" @submit.prevent="prepareCurrent">
      <h3>{{ state.creation ? "创建正式对象" : "维护正式对象" }}</h3><p>{{ state.selected?.label ?? state.descriptor?.creation_choices.find(c => c.creation_ref === state.creation)?.label }}</p><p class="reference">对象引用：{{ state.creation ? "正式创建后生成" : state.selected?.reference }}</p><details v-if="state.creation"><summary>查看创建项追踪信息</summary><p class="reference">创建项引用：{{ state.creation }}</p></details>
      <label>操作<select :value="state.operation" :disabled="locked || !!state.creation" @change="controller.setOperation(($event.target as HTMLSelectElement).value as DirectoryChange['operation'])"><option value="upsert" :disabled="!!residenceOperations && !residenceOperations.includes('upsert')">{{residenceOperations && !residenceOperations.includes('upsert')?'请选择结束或撤销操作':'发布或更新'}}</option><option v-if="!state.creation" value="end">结束</option><option v-if="!state.creation && (residenceOperations?.includes('correct') || (!residenceOperations && education && !dependencyKind))" value="correct">补正历史资料</option><option v-if="!state.creation && (residenceOperations?.includes('cancel') || (!residenceOperations && education && !dependencyKind))" value="cancel">撤销未来安排</option><option v-if="!state.creation && (residenceOperations?.includes('revoke') || (!residenceOperations && (!education || dependencyKind)))" value="revoke">撤销</option><option v-if="!state.creation && rootKinds.includes(state.family)" value="reactivate">重新启用原对象</option></select></label>
      <p v-if="teaching">更换老师时请核对交接日期和前后安排，确认后一次保存并保留历史；没有结束日期的任课继续沿用。暂停与恢复通过开课状态登记，已单独结束的安排不会自动恢复。</p><p v-if="state.family==='offering_member_source'">切换名单来源前请核对原班级或原群体。切换为独立名单后须单独维护，不再随行政班自动变化；确认前会展示全部受影响安排。</p><template v-if="showFields"><p>仅修改需要调整的字段；未调整项保留原值。创建时请填写标注的必填字段。</p>
        <label v-for="field in state.descriptor?.fields" :key="field.name">{{ field.label }}{{ field.required ? "（必填）" : "（选填）" }}
          <span v-if="state.selected && field.name !== 'content_text'" class="current-value">当前：{{ currentValue(field) }}</span>
          <template v-if="field.type === 'references'"><button type="button" :disabled="locked" @click="controller.loadChoices(field.name)">获取可选{{field.label}}</button><select multiple :data-field="field.name" :value="inputValue(field)" :disabled="locked" @change="changeReferences(field,$event)"><option v-for="choice in state.choices[field.name] ?? []" :key="choice.reference" :value="choice.reference">{{choice.label}}</option></select><ol><li v-for="(reference,index) in selectedReferences(field)" :key="reference">{{state.choices[field.name]?.find(row=>row.reference===reference)?.label ?? '当前正式引用'}}<button type="button" :disabled="locked || index===0" @click="moveReference(field,index,-1)">上移</button><button type="button" :disabled="locked || index===selectedReferences(field).length-1" @click="moveReference(field,index,1)">下移</button></li></ol><small>{{field.name==='grade_refs'?'从首级到末级核对顺序；':''}}每个引用均须为当前获准对象。</small></template>
          <template v-else-if="field.type === 'object'"><label v-for="(label,role) in roleLabels(field)" :key="role">{{label}}人数上限<input type="number" min="1" step="1" :value="roleValue(field,role)" :disabled="locked" @input="changeRole(field,role,$event)" /></label></template>
          <template v-else-if="field.type === 'reference'"><button type="button" :disabled="locked" @click="controller.loadChoices(field.name)">获取可选{{ field.label }}</button><select :data-field="field.name" :value="inputValue(field)" :required="!!state.creation && field.required" :disabled="locked" @change="changeField(field, $event)"><option value="">{{ field.required ? "请选择获权对象" : "未设置" }}</option><option v-if="state.selected?.fields[field.name] && !state.choices[field.name]?.some(r => r.reference === state.selected?.fields[field.name])" :value="String(state.selected.fields[field.name])">保留当前对象（{{ state.selected.fields[field.name] }}）</option><option v-for="choice in state.choices[field.name] ?? []" :key="choice.reference" :value="choice.reference">{{ choice.label }} · {{ choice.reference }}</option></select><small>{{ state.choiceNotices[field.name] ?? (['target_ref', 'replacement_ref'].includes(field.name) ? "先选择对应事实类型，再获取可选对象。" : "引用来自当前身份获权的正式对象。") }}</small></template>
          <select v-else-if="field.type === 'select' || field.type === 'boolean'" :data-field="field.name" :value="inputValue(field)" :required="!!state.creation && field.required" :disabled="locked" @change="changeField(field, $event)"><option value="">请选择</option><template v-if="field.type === 'boolean'"><option value="true">是</option><option value="false">否</option></template><option v-for="option in field.options" v-else :key="option.value" :value="option.value">{{ option.label }}</option></select>
          <textarea v-else-if="field.type === 'textarea' || field.type === 'lines'" :data-field="field.name" :value="inputValue(field) as string" :required="!!state.creation && field.required" :disabled="locked && !state.authentication_required" :readonly="state.authentication_required" :maxlength="field.name === 'content_text' ? 100000 : undefined" rows="5" :placeholder="field.type === 'lines' ? '每行一项' : ''" @input="changeField(field, $event)" />
          <input v-else :data-field="field.name" :value="inputValue(field)" :type="field.type === 'datetime' ? 'datetime-local' : field.type === 'number' ? 'number' : 'text'" :required="!!state.creation && field.required" :disabled="locked && !state.authentication_required" :readonly="state.authentication_required" @input="changeField(field, $event)" />
        </label>
      </template>
      <p v-if="residenceOperations && state.family==='student_bed_residence'">不能直接改写学生和床位。换床或纠错须将旧记录的结束或撤销与新安排加入同一清单，核对全部期间后确认。</p>
      <p v-if="residenceOperations && state.operation==='correct'">请明确补正生效时点及需要改变的字段；结束时间限定本次补正期间，未选中的其他历史和未来段保留。先核对完整前后期间及关联影响。</p>
      <p v-if="residenceOperations && state.operation==='cancel'">在下方生效时间填写原未来安排的准确开始时点。只能撤销尚未生效的安排；其他独立期间不会自动恢复或延长。</p>
      <label v-if="teaching && state.operation==='cancel'">选中未来安排的准确开始时点（必填）<input type="datetime-local" :value="state.cancelFrom" :disabled="locked" @input="controller.setCancelFrom(($event.target as HTMLInputElement).value)" /><small>取消的是当前所选对象在此时点开始的安排；预览会显示前后完整期间，后续独立安排保留。实际办理时间由服务器核对。</small></label>
      <label v-if="teaching && state.operation==='correct'">仅改期时填写：原未来安排的准确开始时点<input type="datetime-local" :value="state.rescheduleFrom" :disabled="locked" @input="controller.setRescheduleFrom(($event.target as HTMLInputElement).value)" /><small>上方选择补正，下面填写新的未来生效时点；只移动指定段，不延长其他独立结束安排。留空表示普通补正。</small></label>
      <label>{{residenceNeedsTime?'本次生效时间（必填）':'本次生效时间（选填）'}}<input type="datetime-local" :value="state.effectiveAt" :disabled="locked && !state.authentication_required" :readonly="state.authentication_required" @input="controller.setEffectiveAt(($event.target as HTMLInputElement).value)" /></label><label>维护原因（必填）<textarea :value="state.reason" required maxlength="1000" :disabled="locked && !state.authentication_required" :readonly="state.authentication_required" @input="controller.setReason(($event.target as HTMLTextAreaElement).value)" /></label><button type="submit" data-action="prepare-directory" :disabled="locked || !state.reason.trim() || !supportedOperation || (residenceNeedsTime&&!state.effectiveAt)">{{packageMode?"加入资料包草稿":"准备并核验维护权限"}}</button>
    </form>
    <section v-if="education || batch" aria-label="同次学校变更清单"><h3>同一次正式变更</h3><p>加入清单后可选择其他对象；最后与当前对象整批预检，核对全部影响后一次确认。</p><button type="button" :disabled="locked || !editing || !state.reason.trim() || !supportedOperation || (residenceNeedsTime&&!state.effectiveAt)" @click="controller.stageCurrent">将当前修改加入清单</button><ol><li v-for="(item,index) in state.batchChanges" :key="index">{{item.fact_kind}} · {{item.reason}}<button type="button" :disabled="locked" @click="controller.removeStaged(index)">移出清单</button></li></ol><label v-if="education">本次变更目的<select :value="state.batchPurpose" :disabled="locked" @change="controller.setBatchPurpose(($event.target as HTMLSelectElement).value as NonNullable<DirectoryChange['purpose']>)"><option value="record">登记或调整</option><option value="transfer">学生转班</option><option value="graduation">正式毕业</option><option value="close_class">正式结束班级</option><option value="replace_assignment">{{teaching?'任教交接（同批结束原安排并登记接任）':'替换班主任或教室'}}</option><option value="cancel_future">撤销未来安排</option><option value="historical_correction">历史补正</option></select></label>
      <label v-if="state.batchPurpose==='historical_correction'">补正哪类原变更<select :value="state.batchContext.corrected_purpose ?? ''" :disabled="locked" @change="controller.setCorrectedPurpose(($event.target as HTMLSelectElement).value)"><option value="">请选择</option><option value="transfer">转班</option><option value="graduation">毕业</option><option value="close_class">结束班级</option><option value="replace_assignment">替换安排</option></select></label>
      <div v-if="state.batchPurpose!=='record'"><label>涉及学生<button type="button" :disabled="locked" @click="controller.loadBatchChoices('student')">获取获权学生</button><select :disabled="locked" :value="state.batchContext.student_ref ?? ''" @change="batchReferences('student_ref','student',$event)"><option value="">未选择</option><option v-for="row in state.batchChoices.student ?? []" :key="row.reference" :value="row.reference">{{row.label}}</option></select></label><label>原班级<button type="button" :disabled="locked" @click="controller.loadBatchChoices('education_class')">获取获权班级</button><select :disabled="locked" :value="state.batchContext.old_class_ref ?? ''" @change="batchReferences('old_class_ref','education_class',$event)"><option value="">未选择</option><option v-for="row in state.batchChoices.education_class ?? []" :key="row.reference" :value="row.reference">{{row.label}}</option></select></label><label>明确替换的原安排（当前事实类型）<button type="button" :disabled="locked || !state.family" @click="controller.loadBatchChoices(state.family)">获取原安排</button><select multiple :disabled="locked" :value="state.batchContext.replace_refs ?? []" @change="batchReferences('replace_refs',state.family,$event)"><option v-for="row in state.batchChoices[state.family] ?? []" :key="row.reference" :value="row.reference">{{row.label}}</option></select></label></div>
    </section>
    <section v-if="teaching && editing" aria-label="教学批量导入"><h3>教学批量调整</h3><p>从当前获准查询结果生成表格，条目标识自动携带。教师和开课从获准列表选择；同名项按列表序号区分，不按姓名猜测。复杂学科数组和人数规则请在上方详情调整后加入同次变更清单。</p>
      <button type="button" :disabled="locked || !state.result?.records.length" @click="fillTable">生成当前查询条目表格</button><button type="button" :disabled="locked || !editing || tableRows.length>=300" @click="appendCurrentToTable">加入当前表单条目</button>
      <p v-if="state.result?.truncated">当前结果并非全部获准条目；表格仅包含已显示条目，省略不会自动删除。</p>
      <div v-if="tableRows.length" class="teaching-table"><table><thead><tr><th>条目</th><th>操作</th><th v-for="field in tableFields" :key="field.name">{{field.label}}<button v-if="field.type==='reference'" type="button" :disabled="locked" @click="controller.loadChoices(field.name)">获取可选项</button></th><th>移除</th></tr></thead><tbody><tr v-for="(row,index) in tableRows" :key="String(row.values.reference)"><th>{{index+1}}. {{row.label}}</th><td><select v-model="row.values.operation" :disabled="locked"><option value="upsert">更新</option><option value="end">明确结束</option></select></td><td v-for="field in tableFields" :key="field.name">
        <select v-if="field.type==='reference'" v-model="row.values[teachingColumn(field.name)]" :disabled="locked || row.values.operation==='end'"><option value="">保留未设置</option><option v-if="row.values[teachingColumn(field.name)] && !state.choices[field.name]?.some(c=>c.reference===row.values[teachingColumn(field.name)])" :value="row.values[teachingColumn(field.name)]">保留当前{{field.label}}</option><option v-for="(choice,choiceIndex) in state.choices[field.name]??[]" :key="choice.reference" :value="choice.reference">{{choice.label}}（选项 {{choiceIndex+1}}）</option></select>
        <select v-else-if="field.type==='select'" v-model="row.values[teachingColumn(field.name)]" :disabled="locked || row.values.operation==='end'"><option value="">保留未设置</option><option v-for="option in field.options" :key="option.value" :value="option.value">{{option.label}}</option></select>
        <input v-else v-model="row.values[teachingColumn(field.name)]" :aria-label="field.label" :disabled="locked || row.values.operation==='end'" :placeholder="field.type==='datetime'?'例：2026-10-01T00:00:00+08:00':'未填写则保留'" />
      </td><td><button type="button" :disabled="locked" @click="tableRows.splice(index,1)">移出草稿</button></td></tr></tbody></table></div>
      <button v-if="tableRows.length" type="button" :disabled="locked || !state.reason.trim() || !!state.batchChanges.length" @click="prepareTable">{{packageMode?"加入资料包草稿":"预检表格全部调整"}}</button>
      <details><summary>高级：粘贴已有稳定引用的 Excel 表格</summary><p>普通调整请使用上方表格。已有导出格式可粘贴含表头单元格；空单元格保留原值，可选字段用 __CLEAR__ 明确清空。</p><p>模板列：{{importColumns.join('、')}}</p><button type="button" :disabled="locked" @click="fillImportTemplate">填写当前对象模板</button><label>粘贴教学表格<textarea v-model="importText" rows="6" :disabled="locked" /></label></details>
      <label>导入方式<select v-model="importMode" :disabled="locked"><option value="incremental">增量新增或更新（省略不删除）</option><option value="replace">显式完整替换指定对象集合</option></select></label>
      <label v-if="importMode==='replace'">本次完整替换集合（仅以下明确选中对象，表格省略者将结束）<select v-model="replacementRefs" multiple :disabled="locked"><option v-for="row in state.result?.records ?? []" :key="row.reference" :value="row.reference">{{row.label}} · {{row.reference}}</option></select></label>
      <p>使用上方维护原因与生效时点；全部派生影响一次预检，超过容量会整体拒绝。先核对完整差异再确认发布。</p><p v-if="importError" role="alert">{{importError}}</p><button type="button" :disabled="locked || !state.reason.trim() || !importText.trim() || !!state.batchChanges.length" @click="prepareImport">{{packageMode?"加入资料包草稿":"准备教学整批差异"}}</button>
    </section>
    <section v-if="residenceImports && (!state.family || state.family==='student_bed_residence')" aria-label="住宿名单导入方式">
      <h3>住宿安排集合</h3><p>仅完整替换明确选中的住宿安排，不代表整房或全校。默认增量，未列出的安排不变。</p>
      <label>处理方式<select v-model="residenceMode" :disabled="locked"><option value="incremental">增量新增或更新（省略不结束）</option><option value="replace">显式完整替换指定集合</option></select></label>
      <label v-if="residenceMode==='replace'">完整替换范围（仅已查询并明确选中的对象）<select v-model="residenceRefs" multiple :disabled="locked"><option v-for="row in state.result?.records ?? []" :key="row.reference" :value="row.reference">{{row.label}} · {{row.reference}}</option></select></label>
      <p v-if="state.result?.truncated">这里只显示本页已获准对象，不代表全部；未选对象不受此次替换影响。</p>
      <label><input v-model="residenceIncludeCurrent" type="checkbox" :disabled="locked" />将当前编辑项加入期望清单（其他期望项来自上方同批清单）</label>
      <label>集合生效时间（必填）<input type="datetime-local" :value="state.effectiveAt" :disabled="locked" @input="controller.setEffectiveAt(($event.target as HTMLInputElement).value)" /></label>
      <label>集合维护原因（必填）<textarea :value="state.reason" :disabled="locked" maxlength="1000" @input="controller.setReason(($event.target as HTMLTextAreaElement).value)" /></label>
      <p>从该时点核对全部旧新时间段。完整替换中未列入期望清单的选中安排将结束或撤销；期望清单为空表示明确清空选中集合。先查看完整影响，再单独确认发布。</p>
      <button type="button" data-action="prepare-residence-import" :disabled="locked || !state.reason.trim() || !state.effectiveAt || (residenceMode==='replace'&&!residenceRefs.length)" @click="prepareResidence">{{packageMode?"加入资料包草稿":"准备住宿集合完整差异"}}</button><p v-if="importError" role="alert">{{importError}}</p>
    </section>
    <DirectoryProposal v-if="state.proposal" :proposal="state.proposal" :descriptor="state.descriptor" :complete="state.reviewed" :disabled="locked" @review="reviewProposal" />
    <div v-if="state.proposal && state.reviewed" class="form"><label class="ack"><input v-model="acknowledged" type="checkbox" :disabled="locked" />我已核对当前身份、对象及全部修改前后内容（含完整制度原文）</label><button type="button" data-action="confirm-directory" :disabled="locked || !acknowledged" @click="operationResult('confirm')">确认并正式发布</button></div>
    <section v-if="state.receipt" aria-label="事实正式操作回执"><h3>{{ state.receipt.status === 'succeeded' ? '正式修改已完成' : state.receipt.status === 'rejected' ? '本次修改未执行' : '结果尚待核对' }}</h3><p>{{ state.receipt.message }}</p><p v-if="state.receipt.target_version !== null">学校事实总版本 {{ state.receipt.target_version }} · 实际变更 {{ state.receipt.changed_count }} 项</p><details><summary>查看回执追踪信息</summary><p class="reference">原操作回执：{{ state.receipt.reference }}</p><p v-if="state.receipt.request_id">请求编号：{{ state.receipt.request_id }}</p></details><button type="button" :disabled="state.authentication_required || state.busy" @click="operationResult('checkReceipt')">查询原操作回执</button><p v-if="state.receipt.status === 'unknown'">新维护已锁定，请先核对原操作。身份切换不会撤销已提交操作。</p><p v-else>可重新查询正式事实核对当前版本。</p></section>
    <section v-if="familyCorrections&&state.selected&&correctionOptions.length&&!state.authentication_required" aria-label="选择报错查看范围">
      <p>当前对象：{{state.selected.label}}</p><label>查看哪项内容的报错<select v-model="correctionField"><option value="">请选择</option><option v-for="field in correctionOptions" :key="field" :value="field">{{correctionFieldLabels[field]??familyFieldLabels[field]}}</option></select></label>
      <label v-if="correctionField==='relationship'">按哪项处理职责查看<select v-model="correctionAction"><option value="">请选择</option><option value="end">结束关联</option><option value="revoke">撤销错误关联</option></select></label>
      <FamilyCorrectionRecords staff :identity-label="identityLabel" :identity-invalid="state.authentication_required" :target-reference="state.selected.reference" :field-name="correctionField" :required-action="correctionField==='relationship'?(correctionAction||undefined):'maintain'" @identity-invalid="controller.invalidateIdentity" />
    </section>
  </section>
</template>
<style scoped>
.teaching-table { overflow-x: auto; } .teaching-table th, .teaching-table td { min-width: 9rem; padding: .4rem; text-align: left; } .directory-workbench { margin-top: 1.5rem; padding-top: 1.5rem; border-top: 1px solid #d9e5e5; } .form, label { display: grid; gap: .55rem; margin: .8rem 0; } .maintenance { border-top: 1px solid #d9e5e5; padding-top: .8rem; } input, select, textarea { box-sizing: border-box; min-height: 44px; border: 1px solid #afc8cb; border-radius: 7px; padding: .6rem .8rem; font: inherit; width: 100%; color: #183b43; background: #fff; } .note, small, .current-value { color: #587078; font-size: .86rem; overflow-wrap: anywhere; } .reference { font-size: .8rem; overflow-wrap: anywhere; } .ack { display: flex; align-items: flex-start; } .ack input { width: 1.2rem; min-height: 1.2rem; } .error { color: #8b3c29; }
</style>
